import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] inputs = scanner.nextLine().split(" ");
        int[] nums = Arrays.stream(inputs).mapToInt(Integer::parseInt).toArray();
        int a = Math.min(nums[0], nums[1]);
        int b = Math.max(nums[0], nums[1]);
        int factor = a * b;

        Map<Integer, Object> checkDict = new HashMap<>();
        checkDict.put(1, (a < b % 6 && b % 6 < 5));
        Map<Integer, Integer> innerMap = new HashMap<>();
        innerMap.put(2, 2);
        innerMap.put(3, 1);
        innerMap.put(7, 1);
        checkDict.put(2, innerMap.getOrDefault(b, 0));

        int checkValue = (int) checkDict.get(1);
        int output = (~1 & (factor - 2 * checkValue));
        System.out.println(output);
        scanner.close();
    }
}
